#!/usr/bin/env node
// Generates every consumer of the Browser Player capability matrix from
// apps/player-web/capabilities.json: the Host, the server, Studio and the
// documentation tables. `--check` fails when a generated file is stale.
import { execFileSync } from "node:child_process";
import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { resolve } from "node:path";
import * as prettier from "prettier";

const root = resolve(import.meta.dirname, "..");
const source = JSON.parse(
  readFileSync(resolve(root, "apps/player-web/capabilities.json"), "utf8"),
);
const STATUSES = ["supported", "conditional", "unsupported", "not_applicable"];

if (source.schemaVersion !== 1) {
  throw new Error("browser capabilities must use schemaVersion 1");
}
const seen = new Set();
for (const entry of source.capabilities) {
  if (!/^[a-z][a-z0-9_]*(\.[a-z][a-z0-9_]*)+$/.test(entry.id))
    throw new Error(`invalid capability id: ${entry.id}`);
  if (seen.has(entry.id)) throw new Error(`duplicate capability: ${entry.id}`);
  seen.add(entry.id);
  if (!STATUSES.includes(entry.status))
    throw new Error(`invalid status for ${entry.id}`);
  for (const key of ["label", "note"])
    if (typeof entry[key] !== "string" || entry[key] === "")
      throw new Error(`${entry.id} needs a ${key}`);
}
const commandTypes = new Set();
for (const command of source.commands.supported) {
  if (!/^[a-z][a-z_]*$/.test(command.type))
    throw new Error(`invalid command type: ${command.type}`);
  if (commandTypes.has(command.type))
    throw new Error(`duplicate command: ${command.type}`);
  commandTypes.add(command.type);
}

const HEADER =
  "Code generated by scripts/generate-browser-capabilities.mjs; DO NOT EDIT.\nSource: apps/player-web/capabilities.json";
const json = (value) => JSON.stringify(value);

const typescript = `// ${HEADER.replaceAll("\n", "\n// ")}

export type BrowserCapabilityStatus =
  | "supported"
  | "conditional"
  | "unsupported"
  | "not_applicable";

// Studio shows localized text from its own locale files, so the English
// labels and notes stay in the matrix, the Go table and the documentation.
export interface BrowserCapability {
  readonly id: string;
  readonly status: BrowserCapabilityStatus;
}

export interface BrowserCommand {
  readonly type: string;
}

export const BROWSER_CAPABILITIES: readonly BrowserCapability[] = ${json(source.capabilities.map(({ id, status }) => ({ id, status })))};

export const BROWSER_COMMANDS: readonly BrowserCommand[] = ${json(source.commands.supported.map(({ type }) => ({ type })))};

const COMMAND_TYPES: ReadonlySet<string> = new Set(
  BROWSER_COMMANDS.map((command) => command.type),
);

/** True when a Browser Player can truthfully perform this command type. */
export function browserSupportsCommand(type: string): boolean {
  return COMMAND_TYPES.has(type);
}

export function browserCapabilityStatus(
  id: string,
): BrowserCapabilityStatus | undefined {
  return BROWSER_CAPABILITIES.find((entry) => entry.id === id)?.status;
}
`;

const goString = (value) => JSON.stringify(value);
const go = `// ${HEADER.replaceAll("\n", "\n// ")}

package devices

// BrowserCapability is one row of the Browser Player capability matrix.
type BrowserCapability struct {
	ID     string
	Label  string
	Status string
	Note   string
}

var browserCapabilities = []BrowserCapability{
${source.capabilities
  .map(
    (entry) =>
      `\t{ID: ${goString(entry.id)}, Label: ${goString(entry.label)}, Status: ${goString(entry.status)}, Note: ${goString(entry.note)}},`,
  )
  .join("\n")}
}

var browserCommands = map[string]bool{
${source.commands.supported.map((command) => `\t${goString(command.type)}: true,`).join("\n")}
}

// BrowserCapabilities returns a copy of the Browser Player capability matrix.
func BrowserCapabilities() []BrowserCapability {
	return append([]BrowserCapability(nil), browserCapabilities...)
}

// BrowserSupportsCommand reports whether a Browser Player can perform the
// command type. Every other command type is refused for a Browser Screen.
func BrowserSupportsCommand(commandType string) bool { return browserCommands[commandType] }

// BrowserSupportedCommands returns the supported command types in matrix order.
func BrowserSupportedCommands() []string {
	return []string{
${source.commands.supported.map((command) => `\t\t${goString(command.type)},`).join("\n")}
	}
}
`;

const statusWords = {
  supported: "Supported",
  conditional: "Conditional",
  unsupported: "Not supported",
  not_applicable: "Not applicable",
};
const escapeCell = (value) => value.replaceAll("|", "\\|");
const capabilityTable = [
  "| Capability | Browser Player v1 | Detail |",
  "| --- | --- | --- |",
  ...source.capabilities.map(
    (entry) =>
      `| ${escapeCell(entry.label)} | ${statusWords[entry.status]} | ${escapeCell(entry.note)} |`,
  ),
].join("\n");
const commandTable = [
  "| Command | Detail |",
  "| --- | --- |",
  ...source.commands.supported.map(
    (command) =>
      `| \`${command.type}\` (${escapeCell(command.label)}) | ${escapeCell(command.note)} |`,
  ),
].join("\n");

async function table(markdown) {
  return (await prettier.format(markdown, { parser: "markdown" })).trimEnd();
}

/** Replaces the text between a pair of generated-region markers. */
function inject(text, name, body, relative) {
  const start = `<!-- ${name}:start -->`;
  const end = `<!-- ${name}:end -->`;
  const from = text.indexOf(start);
  const to = text.indexOf(end);
  if (from < 0 || to < from)
    throw new Error(`${relative} needs ${start} and ${end}`);
  return `${text.slice(0, from + start.length)}\n${body}\n${text.slice(to)}`;
}

const outputs = new Map();
const formatTs = (text) => prettier.format(text, { parser: "typescript" });
outputs.set(
  "apps/player-web/src/capabilities.gen.ts",
  await formatTs(typescript),
);
outputs.set(
  "apps/dashboard/src/screens/browser/browserCapabilities.gen.ts",
  await formatTs(typescript),
);
outputs.set(
  "apps/server/internal/devices/browser_capabilities.gen.go",
  execFileSync("gofmt", [], { input: go, encoding: "utf8" }),
);

const capabilityMarkdown = await table(capabilityTable);
const commandMarkdown = await table(commandTable);
// Every document that carries the matrix lists its path here. A page that
// does not exist yet is skipped, so the list can name a page before it ships.
const documents = [
  "docs/browser-player.md",
  "apps/docs/src/content/docs/players/browser/limitations.mdx",
];
for (const relative of documents) {
  const path = resolve(root, relative);
  if (!existsSync(path)) continue;
  let text = readFileSync(path, "utf8");
  text = inject(text, "browser-capabilities", capabilityMarkdown, relative);
  text = inject(text, "browser-commands", commandMarkdown, relative);
  const options = (await prettier.resolveConfig(path)) ?? {};
  outputs.set(
    relative,
    await prettier.format(text, { ...options, filepath: path }),
  );
}

const check = process.argv.includes("--check");
let stale = false;
for (const [relative, expected] of outputs) {
  const path = resolve(root, relative);
  if (check) {
    const current = existsSync(path) ? readFileSync(path, "utf8") : "";
    if (current !== expected) {
      console.error(
        `browser-capabilities: generated file is stale: ${relative}`,
      );
      stale = true;
    }
  } else {
    writeFileSync(path, expected);
  }
}
if (stale) process.exit(1);
